pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        amount = bound(amount, 1, type(uint256).max - 1);
        address owner = address(this);
        vm.deal(address(c), amount + 1);
        vm.prank(owner);
        try c.sendTo(receiver, amount) {
            assertTrue(address(c).balance == 1);
        } catch {
            assertTrue(false);
        }
    }
}
